#pragma GCC optimize("Ofast")
#include <bits/stdc++.h>
using namespace std;
using i64 = int_least64_t;

// Use a completely different structure: use a single class with all methods inline, use a different algorithm: cycle canceling? No, keep successive shortest augmenting path but use a different data structure for edges: use arrays of structs and store reverse index.
// Also use a different way to handle the main loop: use a while loop that finds augmenting paths one by one using Dijkstra, and break when no path.
// Also use a different I/O: use getchar_unlocked for fast input.
class MCF {
    struct Edge {
        size_t to, rev;
        int cap; i64 cost;
    };
    size_t n;
    vector<vector<Edge>> g;
    vector<int> supply;
    vector<i64> potential;
    i64 min_cost, total_cost;
public:
    MCF(size_t _n) : n(_n), g(_n), supply(_n, 0), potential(_n, 0), min_cost(0), total_cost(0) {}
    size_t size() const { return n; }
    void add_edge(size_t from, size_t to, int cap, i64 cost) {
        if (cap <= 0) return;
        if (cost < 0) {
            supply[from] -= cap;
            supply[to] += cap;
            min_cost += cap * cost;
            total_cost -= cap * cost;
            g[to].push_back({from, (size_t)g[from].size(), cap, -cost});
            g[from].push_back({to, (size_t)g[to].size() - 1, 0, cost});
        } else {
            total_cost += cap * cost;
            g[from].push_back({to, (size_t)g[to].size(), cap, cost});
            g[to].push_back({from, (size_t)g[from].size() - 1, 0, -cost});
        }
    }
    void supply(size_t node, int vol) { supply[node] += vol; }
    bool flow() {
        const i64 INF = total_cost + 1;
        while (true) {
            vector<i64> dist(n, INF);
            vector<size_t> prevv(n, n), preve(n, n);
            priority_queue<pair<i64, size_t>, vector<pair<i64, size_t>>, greater<pair<i64, size_t>>> pq;
            for (size_t v = 0; v < n; ++v) {
                if (supply[v] > 0) {
                    dist[v] = 0;
                    pq.push({0, v});
                }
            }
            while (!pq.empty()) {
                auto [d, v] = pq.top(); pq.pop();
                if (d != dist[v]) continue;
                potential[v] -= d;
                if (potential[v] > INF) potential[v] = INF;
                dist[v] = INF;
                for (size_t i = 0; i < g[v].size(); ++i) {
                    Edge &e = g[v][i];
                    if (e.cap == 0) continue;
                    i64 nd = potential[v] + e.cost - potential[e.to];
                    if (nd < dist[e.to]) {
                        dist[e.to] = nd;
                        prevv[e.to] = v;
                        preve[e.to] = i;
                        pq.push({nd, e.to});
                    }
                }
            }
            // Find a sink with negative supply and a path
            size_t sink = n;
            for (size_t v = 0; v < n; ++v) {
                if (supply[v] < 0 && prevv[v] != n) {
                    sink = v;
                    break;
                }
            }
            if (sink == n) break; // no augmenting path
            // Compute residual capacity
            int add = -supply[sink];
            for (size_t v = sink; v != n && prevv[v] != n; v = prevv[v]) {
                Edge &e = g[prevv[v]][preve[v]];
                add = min(add, e.cap);
            }
            // Augment
            for (size_t v = sink; v != n && prevv[v] != n; v = prevv[v]) {
                Edge &e = g[prevv[v]][preve[v]];
                e.cap -= add;
                g[v][e.rev].cap += add;
            }
            supply[prevv[sink]] -= add;
            supply[sink] += add;
            min_cost += potential[sink] * add;
        }
        for (int s : supply) if (s > 0) return false;
        return true;
    }
    i64 optimal() { return flow() ? min_cost : -1; }
};

// Fast input using getchar_unlocked
int read_int() {
    int x = 0, c = getchar_unlocked();
    while (c < '0' || c > '9') c = getchar_unlocked();
    while (c >= '0' && c <= '9') {
        x = x * 10 + (c - '0');
        c = getchar_unlocked();
    }
    return x;
}

int main() {
    int n = read_int(), m = read_int(), k = read_int(), c = read_int(), d = read_int();
    const int tlim = 105;
    MCF mcf(6100);
    for (int i = 0; i < k; ++i) {
        int j = read_int() - 1;
        mcf.supply(j, 1);
    }
    for (int i = 0; i < m; ++i) {
        int u = read_int() - 1, v = read_int() - 1;
        for (int t = 0; t < tlim; ++t) {
            int nu = u + n;
            int nv = v + n;
            for (int x = 0; x < k; ++x) {
                mcf.add_edge(u, nv, 1, c + d * (x * 2 + 1));
                mcf.add_edge(v, nu, 1, c + d * (x * 2 + 1));
            }
            u = nu;
            v = nv;
        }
    }
    for (int i = 1; i < n; ++i) {
        for (int t = 0; t < tlim; t++) {
            mcf.add_edge(n * t + i, n * (t + 1) + i, k, c);
        }
    }
    const int dst = mcf.size() - 1;
    mcf.supply(dst, -k);
    for (int t = 0; t <= tlim; ++t) mcf.add_edge(t * n, dst, k, 0);
    printf("%lld\n", (long long)mcf.optimal());
    return 0;
}
